 1疊算(iteration) 2重複(repetition) 3回復(recovery)     4遞廻(recursion)                   for(j=0 ; j<i ; j++)
                                                                                       printf("%4d",i*j);

下列程式執行後，會輸出甚麼結果？
            j = 0;                                                                 #include <stdio.h>
            sum = 0;                                                               void silly(int *a, int b)
            do {                                                                   {     *a = b; }
                  j++;                                                             int main(void)
                  sum += i + j;                                                    {
            }while(j<i);                                                                int x[]={10, 12, 5, 8, 2, 15, 14};
